#include "resident/storage/common_checkpoint.hpp"
#include <algorithm>
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool v,const char* s){++checks;if(!v)throw std::runtime_error(s);}}
int main(){try{
    GrowthRecoveryState state;state.services.insert("action:1",{"patient","provider","role","place",GrowthRecoveryMethod::safe_lodging,4,2,{}});GrowthRecoveryStep step;step.action_id="action:1";step.tick=5;step.ordinal=1;step.before={1,0};step.after={1,1};step.offered_points=step.used_points=1;state.credits.insert("recovery:2",step);GrowthRecoveryClosure closed;closed.action_id="action:1";closed.tick=5;closed.provided_half_days=1;closed.reason="cancelled";closed.commit_result_id="result:4";closed.commit_actor_id="patient";closed.commit_kind="recovery_cancel";closed.commit_request_seq=1;closed.commit_revision=1;state.closures.insert("recovery:3",closed);
    auto json=encode_growth_recovery_state(state);auto read=decode_growth_recovery_state(json);check(read.ok&&compare_boundary(json,encode_growth_recovery_state(read.value)).exact(),"all typed records exact JSON");auto reordered=json;std::reverse(reordered.as<BoundaryValue::Dict>()->begin(),reordered.as<BoundaryValue::Dict>()->end());read=decode_growth_recovery_state(reordered);check(read.ok&&compare_boundary(reordered,encode_growth_recovery_state(read.value)).exact(),"root field order preserved");
    CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);auto binary=state;check(visit_growth_recovery_checkpoint(writer,binary).ok&&writer.finish().ok,"independent binary source");check(writer.schema_features==0,"no new Growth or Common feature bit");GrowthRecoveryState restored;CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(bytes));check(visit_growth_recovery_checkpoint(reader,restored).ok&&reader.finish().ok&&compare_boundary(json,encode_growth_recovery_state(restored)).exact(),"binary roundtrip original shape");bytes.pop_back();CodecVisitor truncated(static_cast<const CodecVisitor::Buffer&>(bytes));check(!visit_growth_recovery_checkpoint(truncated,restored).ok||!truncated.finish().ok,"truncated final record rejected");
    auto bad=json;bad.as<BoundaryValue::Dict>()->emplace_back("version",BoundaryValue{Integer{1}});check(!decode_growth_recovery_state(bad).ok,"duplicate root version rejected");bad=json;bad.find("services")->find("action:1")->as<BoundaryValue::Dict>()->emplace_back("actor_id",BoundaryValue{StableId{"intruder"}});check(!decode_growth_recovery_state(bad).ok,"service actor duplicate rejected before first-match");bad=json;bad.find("credits")->find("recovery:2")->as<BoundaryValue::Dict>()->emplace_back("injury_after",BoundaryValue{Integer{0}});check(!decode_growth_recovery_state(bad).ok,"credit value duplicate rejected");bad=json;bad.find("closures")->find("recovery:3")->as<BoundaryValue::Dict>()->emplace_back("cause_fact_id",BoundaryValue{StableId{"fake"}});check(!decode_growth_recovery_state(bad).ok,"closure source duplicate rejected");bad=json;*bad.find("version")=BoundaryValue{Integer{2}};check(!decode_growth_recovery_state(bad).ok,"unknown version is not interpreted as old shape");bad=json;*bad.find("services")->find("action:1")->find("method")=BoundaryValue{Integer{2}};check(!decode_growth_recovery_state(bad).ok,"unsupported recovery method rejected");bad=json;bad.find("credits")->find("recovery:2")->as<BoundaryValue::Dict>()->emplace_back("money_paid",BoundaryValue{Integer{20}});check(!decode_growth_recovery_state(bad).ok,"second payment ledger field rejected");
    bad=json;bad.find("closures")->find("recovery:3")->as<BoundaryValue::Dict>()->emplace_back("commit_result_id",BoundaryValue{StableId{"result:99"}});check(!decode_growth_recovery_state(bad).ok,"duplicate permanent result binding rejected");bad=json;*bad.find("closures")->find("recovery:3")->find("commit_result_id")=BoundaryValue{StableId{}};check(!decode_growth_recovery_state(bad).ok,"partially absent binding cannot masquerade as candidate");
    std::cout<<"GROWTH_RECOVERY_CODEC "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<"GROWTH_RECOVERY_CODEC "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
